// ==== EDITA AQUÍ TU NÚMERO DE WHATSAPP (con código de país, sin + ni espacios) ====
// Enlace real de WhatsApp Business "Plantas Odette Ygg" (extraído del QR oficial)
const WHATSAPP_LINK_BASE = "https://wa.me/message/UO5FO3Z2LW4NO1";
// Alternativa para enviar mensajes con texto prellenado. Si tienes un número, colócalo en PHONE_NUMBER.
const WHATSAPP_API_SEND = "https://api.whatsapp.com/send";
const PHONE_NUMBER = "569940037837"; // Número de la marca (código de país + número, sin + ni espacios)

function sanitizeWaText(text){
  return String(text || '').replace(/[\u{1F300}-\u{1FAFF}\u2600-\u26FF]/gu, '');
}

function buildWaUrl(text){
  const msg = encodeURIComponent(sanitizeWaText(text));
  if(PHONE_NUMBER && PHONE_NUMBER.trim()){
    // Usar wa.me para abrir directamente la app en dispositivos móviles
    return `https://wa.me/${PHONE_NUMBER}?text=${msg}`;
  }
  // Si existe un enlace de mensaje directo (WHATSAPP_LINK_BASE), úsalo para dirigir al chat de la marca
  if(WHATSAPP_LINK_BASE && WHATSAPP_LINK_BASE.trim()){
    return `${WHATSAPP_LINK_BASE}?text=${msg}`;
  }
  return `${WHATSAPP_API_SEND}?text=${msg}`;
}
