function setProductPrices(name, prices, category){
  const product = PRODUCTS.find(item => item.n.toLowerCase() === name.toLowerCase());
  if(!product) return;
  product.p = prices.length > 1 ? `Desde ${prices[0]}` : prices[0];
  if(prices.length > 1) product.sizes = prices.map((price, index) => ({l: ['S','M','L'][index] || `Opción ${index + 1}`, p:price}));
  else delete product.sizes;
}

