function normalizeProductName(value){
  return value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
}
incomingProductUpdates.forEach(update => {
  const aliases = update.names.map(normalizeProductName);
  let product = PRODUCTS.find(item => aliases.includes(normalizeProductName(item.n)));
  if(!product){
    product = {n:update.name, c:update.category, care:'Consulta disponibilidad y cuidados por WhatsApp.'};
    PRODUCTS.push(product);
  }
  const sizeEntries = update.prices.filter(([label, price]) => label && price);
  product.p = sizeEntries.length > 1 ? `Desde ${sizeEntries[0][1]}` : update.prices[0][1];
  product.sizes = sizeEntries.map(([label, price]) => ({l:label, p:price}));
  if(!product.sizes.length) delete product.sizes;
  if(update.image) product.img = update.image;
});
