const suppliedPhotoPath = name => `img/productos/${name}`;
const findProductByName = name => PRODUCTS.find(item => normalizeProductName(item.n) === normalizeProductName(name));
const setProductPhoto = (name, fileName) => {
  const product = findProductByName(name);
  if(product) product.img = suppliedPhotoPath(fileName);
};
const clearProductPhoto = name => {
  const product = findProductByName(name);
  if(product) delete product.img;
};

const addPhotoProduct = (name, category, fileName) => {
  let product = findProductByName(name);
  if(!product){
    product = {n:name, c:category, care:'Consulta disponibilidad y cuidados por WhatsApp.'};
    PRODUCTS.push(product);
  }
  product.img = suppliedPhotoPath(fileName);
};

