function waterDropsHTML(level, size){
  if(level === null || level === undefined) return "";
  let s = size || 11;
  let drops = "";
  for(let i=1;i<=5;i++){
    drops += `<span class="drop ${i<=level?'filled':''}" style="font-size:${s}px">💧</span>`;
  }
  return drops;
}

