// ----- Carrito (simple) -----
const CART = [];
function addToCart(idx){
  const p = PRODUCTS[idx];
  if(!p) return;
  const selectedSize = p.sizes && p.sizes[0] ? p.sizes[0] : null;
  const size = selectedSize ? selectedSize.l : null;
  const price = selectedSize ? selectedSize.p : p.p;
  const image = productImageSrc(p.img);
  const existing = CART.find(i=>i.n===p.n && i.img===image && (i.size||'')===(size||''));
  if(existing){ existing.q += 1; } else { CART.push({n: p.n, q:1, price, img: image, size}); }
  renderCartUI();
  updateCartBadge();
}
function addModalToCart(){
  const p = PRODUCTS[currentProductIndex];
  if(!p) return;
  const selectedSize = p.sizes && currentSizeLabel
    ? p.sizes.find(item => item.l === currentSizeLabel)
    : null;
  const size = currentSizeLabel || (p.sizes && p.sizes[0]?p.sizes[0].l:null);
  const image = productImageSrc(p.img);
  const existing = CART.find(i=>i.n===p.n && i.img===image && (i.size||'')===(size||''));
  const selectedPrice = selectedSize ? selectedSize.p : (p.sizes&&p.sizes[0]) ? p.sizes[0].p : p.p;
  if(existing) existing.q += 1; else CART.push({n:p.n,q:1,price:selectedPrice,img:image,size:size});
  renderCartUI(); updateCartBadge();
}
function updateCartBadge(){
  const count = CART.reduce((s,i)=>s+i.q,0);
  const el = document.getElementById('cartCount');
  if(!el) return;
  if(count>0){ el.style.display='flex'; el.textContent = count; } else { el.style.display='none'; }
}
function toggleCart(){ const d=document.getElementById('cartDrawer'); const isOpen = d.classList.toggle('open'); d.setAttribute('aria-hidden', String(!isOpen)); }
function renderCartUI(){ const itemsEl=document.getElementById('cartItems'); if(!itemsEl) return; if(CART.length===0){ itemsEl.innerHTML='<div style="padding:12px;color:#666">Tu carrito está vacío.</div>'; return; } itemsEl.innerHTML = CART.map((it,idx)=> `<div class="cart-item"><img src="${it.img}" alt=""><div class="meta"><div class="name">${it.n}</div><div class="qty">Cantidad: ${it.q}${it.size? ' · ' + it.size : ''} · ${it.price||''}</div></div><div><button onclick="removeItem(${idx})" style="background:none;border:none;color:#c33;font-weight:800;cursor:pointer">✕</button></div></div>`).join(''); }
function removeItem(i){ CART.splice(i,1); renderCartUI(); updateCartBadge(); }
function clearCart(){ CART.length=0; renderCartUI(); updateCartBadge(); }
function sendCartViaWhatsApp(){
  if(CART.length===0) { alert('El carrito está vacío.'); return; }
  let lines = ['Hola! Quisiera hacer el siguiente pedido desde el catálogo:'];
  CART.forEach(it=>{ lines.push(`${it.q} x ${it.n}${it.size? ' (Tamaño '+it.size+')':''} — ${it.price||''}`); });
  lines.push('\n¿Me confirman disponibilidad y envío? Gracias!');
  const msgText = lines.join('\n');
  const url = buildWaUrl(msgText);
  window.open(url,'_blank');
}
// initialize cart UI
renderCartUI(); updateCartBadge();

